#Requires -Version 5.1
# fix-dashboard-asignaciones-live.ps1
# El dashboard cargaba TODAS las asignaciones de la BD una sola vez
# y no las actualizaba al navegar entre semanas.
# Fix 1: la query inicial ya filtra por semana actual +/- 30 dias
#         (igual que el planificador) para evitar datos cacheados
# Fix 2: navigateDate recarga las asignaciones de la nueva semana
#         desde Supabase cada vez que el usuario navega

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> Fix dashboard asignaciones live" -ForegroundColor Cyan

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\dashboard\page.tsx"), $bytes)

$c = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\dashboard\page.tsx"), [System.Text.Encoding]::UTF8)
if ($c.Contains('gte("fecha_fin"')) { Write-Host "  OK: query con filtro de fechas" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($c.Contains("Recargar asignaciones")) { Write-Host "  OK: navigateDate recarga asignaciones" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }

Write-Host ""
Write-Host "  git add src\app\dashboard\page.tsx"
Write-Host '  git commit -m "fix: dashboard recarga asignaciones al navegar semanas"'
Write-Host "  git push"
